declare(strict_types=1);require __DIR__.'/bootstrap.php';require __DIR__.'/coa_client.php';if($_SERVER['REQUEST_METHOD']!=='POST')json_response(array('ok'=>false,'error'=>'Método não permitido.'),405);
try{$cache='/var/cache/mkauth-huawei-online/coa-health.json';if(is_file($cache)&&time()-(int)filemtime($cache)<300){$saved=json_decode((string)file_get_contents($cache),true);if(is_array($saved)&&!empty($saved['ok']))json_response($saved);}$c=addon_config();$nas=(string)($c['nas_ip']??'');if(!filter_var($nas,FILTER_VALIDATE_IP))throw new RuntimeException('NAS-IP-Address do Huawei não configurado.');$d=db();$secret=coa_secret($d,$nas);$d->close();$probe='mkauth-addon-coa-probe-'.bin2hex(random_bytes(4));$r=coa_send($nas,$secret,array('User-Name'=>$probe,'NAS-IP-Address'=>$nas));if(!$r['communicated'])throw new RuntimeException('Huawei não respondeu ao CoA na porta 3799. Confira a chave, rota e radius-server authorization.');$answer=array('ok'=>true,'message'=>'CoA comunicando com o Huawei na porta 3799 (resposta validada).','response'=>$r['ok']?'ACK':'NAK de teste esperado');if(!is_dir(dirname($cache)))@mkdir(dirname($cache),0750,true);@file_put_contents($cache,json_encode($answer),LOCK_EX);json_response($answer);}catch(Throwable$e){json_response(array('ok'=>false,'error'=>$e->getMessage()),500);}
